"""Create an interactive offline browser replay of the *actual* AI demo log.

The HTML file embeds simulation events and held-out evaluation metrics. It uses
only Python's standard library, and never changes the trained Q-table.
"""
import argparse
import contextlib
import io
import json
from pathlib import Path
import webbrowser

from main import SCENARIOS, run_demo
from settings import ROOT, load_config

SCENARIO_LABELS = {
    'normal': 'Normal traffic',
    'rush': 'School rush hour',
    'shift': 'Changing demand',
    'uncertainty': 'Uncertain camera',
    'failures': 'Manual / API failures',
}


def read_events(path):
    """Load exactly the event records generated by the simulation."""
    path = Path(path)
    if not path.is_file():
        raise FileNotFoundError(f'No replay data at {path}. Run without --use-saved first.')
    with path.open(encoding='utf-8') as stream:
        events = [json.loads(line) for line in stream if line.strip()]
    if not events:
        raise ValueError(f'Empty event log: {path}')
    for event in events:
        if 'state_after' not in event or 'mode' not in event or 'action' not in event:
            raise ValueError(f'Event log has an incompatible record: {path}')
    return events


def create_dashboard(output, scenarios, summary=None, seed=2026):
    """Produce a self-contained HTML dashboard using actual records."""
    payload = {'scenarios': scenarios, 'scenario_labels': SCENARIO_LABELS,
               'evaluation': summary or [], 'seed': seed}
    raw = json.dumps(payload, ensure_ascii=False, allow_nan=False)
    # JSON is embedded in a non-executable script tag; prevent early termination.
    raw = raw.replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    html = HTML_TEMPLATE.replace('__DATA_JSON__', raw)
    output = Path(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(html, encoding='utf-8')
    return output


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--scenario', choices=('all',) + SCENARIOS, default='all')
    parser.add_argument('--steps', type=int, default=120)
    parser.add_argument('--seed', type=int, default=2026)
    parser.add_argument('--config', default=str(ROOT / 'config.json'))
    parser.add_argument('--model', default='artifacts/q_table.json')
    parser.add_argument('--output', default='artifacts')
    parser.add_argument('--open', action='store_true', help='open visual replay in the default browser')
    parser.add_argument('--use-saved', action='store_true',
                        help='replay existing logs without re-running the simulation')
    args = parser.parse_args()
    if not 1 <= args.steps <= 7200:
        parser.error('--steps must be between 1 and 7200')
    config = load_config(args.config)
    output = Path(args.output)
    selected = SCENARIOS if args.scenario == 'all' else (args.scenario,)
    scenario_events = {}
    for scenario in selected:
        path = output / 'demos' / scenario
        if not args.use_saved:
            # Reuse exactly the same simulation and event logger as main.py.
            # Hide the long text trace; the browser is the presentation surface.
            demo_args = argparse.Namespace(model=args.model, seed=args.seed,
                                           steps=args.steps, every=args.steps + 1,
                                           verbose=False, delay=0.0, untrained=False)
            with contextlib.redirect_stdout(io.StringIO()):
                run_demo(config, demo_args, scenario, path)
        events = read_events(path / 'execution.jsonl')
        scenario_events[scenario] = events
        print(f'{SCENARIO_LABELS[scenario]}: {len(events)} decisions loaded')
    summary_path = output / 'summary.json'
    evaluation = json.loads(summary_path.read_text(encoding='utf-8')) if summary_path.is_file() else []
    dashboard = create_dashboard(output / 'traffic_dashboard.html', scenario_events, evaluation, args.seed)
    print(f'\nInteractive junction replay saved to: {dashboard.resolve()}')
    print('Open the HTML file in Chrome or Edge, or run with --open.')
    print('The diagram replays simulation logs; it does not control real traffic lights.')
    if args.open:
        webbrowser.open(dashboard.resolve().as_uri())


